<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request,refresh,type Page,type Role,type Permission,type System} from '../auth';
const roles=ref<Role[]>([]),page=ref(0),total=ref(0),name=ref(''),editing=ref<Role|null>(null),selected=ref<Role|null>(null),assigned=ref<Permission[]>([]),systems=ref<System[]>([]),systemId=ref(''),permissions=ref<Permission[]>([]),permissionId=ref(''),error=ref('');
async function run(action:()=>Promise<void>){error.value='';try{await action()}catch(e){error.value=(e as Error).message}}
async function load(){const data=await request<Page<Role>>(`/api/roles?page=${page.value}`);roles.value=data.items;total.value=data.total}
async function save(){await run(async()=>{await request(editing.value?`/api/roles/${editing.value.id}`:'/api/roles',editing.value?'PATCH':'POST',{name:name.value});editing.value=null;name.value='';await load()})}
async function remove(role:Role){if(confirm(`删除角色 ${role.name}？请先处理关联。`))await run(async()=>{await request(`/api/roles/${role.id}`,'DELETE');await load()})}
async function select(role:Role){await run(async()=>{selected.value=role;assigned.value=await request<Permission[]>(`/api/roles/${role.id}/permissions`);systems.value=(await request<Page<System>>('/api/systems?size=100')).items})}
async function loadPermissions(){await run(async()=>{permissionId.value='';permissions.value=systemId.value?(await request<Page<Permission>>(`/api/systems/${systemId.value}/permissions?size=100`)).items:[]})}
async function grant(){await run(async()=>{if(!selected.value||!permissionId.value)return;await request(`/api/roles/${selected.value.id}/permissions/${permissionId.value}`,'PUT');await select(selected.value);await refresh()})}
async function revoke(permission:Permission){await run(async()=>{if(!selected.value)return;await request(`/api/roles/${selected.value.id}/permissions/${permission.id}`,'DELETE');await select(selected.value);await refresh()})}
onMounted(()=>run(load));
</script>
<template><h2>本部门角色</h2><p role="alert" class="error">{{error}}</p><table><thead><tr><th>角色名称</th><th>操作</th></tr></thead><tbody><tr v-for="role in roles" :key="role.id"><td>{{role.name}}</td><td><button @click="editing=role;name=role.name">重命名</button><button @click="select(role)">配置权限</button><button @click="remove(role)">删除</button></td></tr></tbody></table><div class="pager"><button :disabled="page===0" @click="page--;run(load)">上一页</button><span>第 {{page+1}} 页 共 {{total}} 个</span><button :disabled="(page+1)*20>=total" @click="page++;run(load)">下一页</button></div><form @submit.prevent="save"><label>{{editing?'重命名角色':'新建角色'}}<input v-model.trim="name" required maxlength="100"></label><button>保存</button><button type="button" @click="editing=null;name=''">取消</button></form>
 <section v-if="selected"><h3>{{selected.name}} 的权限</h3><table><thead><tr><th>系统编号</th><th>权限编码</th><th>名称</th><th>操作</th></tr></thead><tbody><tr v-for="permission in assigned" :key="permission.id"><td>{{permission.systemId}}</td><td>{{permission.code}}</td><td>{{permission.name}}</td><td><button @click="revoke(permission)">撤销</button></td></tr></tbody></table><form @submit.prevent="grant"><label>系统<select v-model="systemId" required @change="loadPermissions"><option value="">请选择</option><option v-for="system in systems" :key="system.id" :value="system.id">{{system.name}}</option></select></label><label>权限<select v-model="permissionId" required><option value="">请选择</option><option v-for="permission in permissions" :key="permission.id" :value="permission.id">{{permission.code}} {{permission.name}}</option></select></label><button>授予</button><button type="button" @click="selected=null">关闭</button></form></section>
</template>
